import { createClient } from '@supabase/supabase-js';

// NOTE: In a real deployment, these would come from process.env
// For this portfolio demo, we will gracefully degrade if keys are missing.
const SUPABASE_URL = process.env.SUPABASE_URL || '';
const SUPABASE_KEY = process.env.SUPABASE_ANON_KEY || '';

export const supabase = (SUPABASE_URL && SUPABASE_KEY) 
  ? createClient(SUPABASE_URL, SUPABASE_KEY)
  : null;

// Mock function to simulate data fetching if Supabase isn't connected
export const fetchContent = async () => {
  if (!supabase) {
    console.warn("Supabase not configured. Using local mock data.");
    return null;
  }
  const { data, error } = await supabase.from('site_content').select('*').single();
  if (error) throw error;
  return data;
};

// Mock function to simulate form submission
export const submitInquiry = async (formData: any) => {
  console.log("Submitting inquiry:", formData);
  if (supabase) {
    const { error } = await supabase.from('inquiries').insert([formData]);
    if (error) throw error;
  } else {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 1000));
  }
  return true;
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'whatsapp';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  fullWidth = false,
  className = '',
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-medium transition-all duration-200 rounded-md focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-primary hover:bg-blue-700 text-white focus:ring-primary shadow-lg hover:shadow-xl hover:-translate-y-0.5",
    secondary: "bg-secondary hover:bg-blue-900 text-white focus:ring-secondary",
    outline: "border-2 border-primary text-primary hover:bg-blue-50 focus:ring-primary",
    whatsapp: "bg-green-500 hover:bg-green-600 text-white focus:ring-green-500 shadow-lg"
  };

  const sizes = {
    sm: "px-3 py-1.5 text-sm",
    md: "px-6 py-2.5 text-base",
    lg: "px-8 py-3.5 text-lg"
  };

  const width = fullWidth ? "w-full" : "";

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${width} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;

