const Contact = ({ preSelectedPlan }: { preSelectedPlan: string }) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: '',
    plan: preSelectedPlan
  });
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');

  useEffect(() => {
    if (preSelectedPlan) {
      setFormData(prev => ({ ...prev, plan: preSelectedPlan }));
      scrollToSection('contact'); // Ensure we scroll when a plan is picked
    }
  }, [preSelectedPlan]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('submitting');
    try {
      await submitInquiry(formData);
      setStatus('success');
      setFormData({ name: '', email: '', phone: '', message: '', plan: '' });
    } catch (error) {
      console.error(error);
      setStatus('error');
    }
  };

  return (
    <section id="contact" className="py-20 bg-primary"> {/* Primary Blue Background */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Top Header */}
