const App = () => {
  const [currentHash, setCurrentHash] = useState(window.location.hash);
  const [selectedPlan, setSelectedPlan] = useState('');

  useEffect(() => {
    const handleHashChange = () => {
      setCurrentHash(window.location.hash);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    };
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const handlePlanSelect = (p: string) => {
    setSelectedPlan(p);
    scrollToSection('contact');
  };

  const renderContent = () => {
    const landingHashes = ['', '#home', '#about', '#services', '#portfolio', '#pricing', '#contact', '#faq'];
    if (landingHashes.includes(currentHash)) {
      return <LandingPage onSelectPlan={handlePlanSelect} selectedPlan={selectedPlan} />;
    }
    switch (currentHash) {
      case '#privacy': return <PrivacyPolicy />;
      case '#terms': return <TermsConditions />;
      case '#admin': return <AdminPlaceholder />;
      default: return <LandingPage onSelectPlan={handlePlanSelect} selectedPlan={selectedPlan} />;
    }
  };

  return (
    <div className="antialiased font-sans selection:bg-primary selection:text-white overflow-x-hidden">
      <Navbar />
      <AnimatePresence mode="wait">
        <main key={currentHash}>
          {renderContent()}
        </main>
      </AnimatePresence>
      <Footer />
      <FloatingWhatsApp />
    </div>
  );
};

