                 <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center mr-8 group-hover:bg-primary transition-colors">
                   <Mail className="w-8 h-8" />
                 </div>
                 <div>
                   <p className="text-xs font-black text-primary uppercase tracking-widest mb-1">Email me</p>
                   <p className="text-2xl font-black">riddhaanleo@gmail.com</p>
                 </div>
               </div>
               <div className="flex items-center group">
                 <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center mr-8 group-hover:bg-green-500 transition-colors">
                   <MessageCircle className="w-8 h-8" />
                 </div>
                 <div>
                   <p className="text-xs font-black text-green-500 uppercase tracking-widest mb-1">WhatsApp</p>
                   <p className="text-2xl font-black">+91 95212 07156</p>
                 </div>
               </div>
            </div>
          </div>

          <div className="bg-white rounded-[48px] p-8 md:p-12 text-gray-900 shadow-2xl">
            {status === 'success' ? (
              <motion.div 
                initial={{ opacity: 0, scale: 0.9 }}
