const ComparisonRow = ({ feature, val1, val2, val3, index, key }: { feature: string, val1: any, val2: any, val3: any, index: number, key?: React.Key }) => {
  const renderVal = (val: any) => {
    if (val === true) return <Check className="w-5 h-5 text-green-500 mx-auto" />;
    if (val === false) return <X className="w-5 h-5 text-red-500 mx-auto" />;
    return <span className="text-gray-600 text-sm font-medium">{val}</span>;
  };

  return (
    <motion.tr 
      key={key}
      initial={{ opacity: 0, x: -20 }}
      whileInView={{ opacity: 1, x: 0 }}
      viewport={{ once: true }}
      transition={{ delay: index * 0.05 }}
      className="border-b border-gray-100 hover:bg-gray-50/50 transition-colors"
    >
      <td className="py-5 px-6 text-sm font-black text-gray-900">{feature}</td>
      <td className="py-5 px-4 text-center bg-blue-50/10">{renderVal(val1)}</td>
      <td className="py-5 px-4 text-center bg-blue-50/30">{renderVal(val2)}</td>
      <td className="py-5 px-4 text-center bg-blue-50/10">{renderVal(val3)}</td>
    </motion.tr>
  );
};

