const App = () => {
  const [isLogged, setIsLogged] = useState(false);
  const [loading, setLoading] = useState(true);
  const [hash, setHash] = useState(window.location.hash);

  const [settings, setSettings] = useState<SiteSettings>({
    id: '1', site_name: DEFAULT_NAME, tagline: 'PREMIUM FREELANCE STUDIO', logo_url: '', 
    whatsapp_number: DEFAULT_WA, contact_phone: '+91 95212 07156', contact_email: 'riddhaanleo@gmail.com',
    address: 'India', instagram_url: '#', twitter_url: '#', linkedin_url: '#', footer_text: '',
    seo_description: 'Premium hand-crafted websites designed specifically for Indian startups and professionals.'
  });

  const [plans, setPlans] = useState<PricingPlan[]>(DEFAULT_PRICING.map(p => ({
    id: p.id, name: p.name, price: p.price, pages: p.pages, features: p.features, is_popular: p.isPopular || false
  })));
  const [services, setServices] = useState<Service[]>(DEFAULT_SERVICES.map(s => ({
    id: s.id, title: s.title, description: s.description, icon: s.icon, status: 'active'
  })));
  const [portfolio, setPortfolio] = useState<Project[]>(DEFAULT_PORTFOLIO.map(p => ({
    id: p.id, title: p.title, category: p.category, image: p.image, description: p.description, link: p.link, status: 'published'
  })));
  const [inquiries, setInquiries] = useState<Inquiry[]>([]);

  useEffect(() => {
    const init = async () => {
      // Sync local hash
      const handleHash = () => setHash(window.location.hash);
      window.addEventListener('hashchange', handleHash);

      // Load initial data from Supabase
      try {
        const [s, p, sv, pt, inq] = await Promise.all([
          db.getSiteSettings(), db.getPricingPlans(), db.getServices(), db.getPortfolio(), db.getInquiries()
        ]);
        if (s) setSettings(s);
        if (p.length) setPlans(p);
        if (sv.length) setServices(sv);
        if (pt.length) setPortfolio(pt);
        if (inq.length) setInquiries(inq);
      } catch (err) {
        console.warn("Supabase load failed, using local fallbacks.");
      }

      setIsLogged(db.isAdminLoggedIn());
      setLoading(false);
      return () => window.removeEventListener('hashchange', handleHash);
    };
    init();
  }, []);

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="w-12 h-12 text-primary animate-spin" /></div>;

  // --- RENDERING LOGIC ---
  if (hash === '#admin') {
    if (!isLogged) return <AdminLogin onLogin={() => setIsLogged(true)} />;
    return <AdminDashboard 
      inquiries={inquiries} 
      onLogout={() => { db.logoutAdmin(); setIsLogged(false); }} 
      stats={{ services: services.length, projects: portfolio.length }} 
    />;
  }

  return (
    <div className="antialiased selection:bg-primary selection:text-white">
      <Navbar />
      <Hero settings={settings} />
      <About />
      <Services services={services} />
      <Portfolio items={portfolio} />
      <Pricing plans={plans} onSelect={() => scrollToSection('contact')} />
      <section id="contact" className="py-32 bg-gray-900 text-white">
        <div className="max-w-7xl mx-auto px-4">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-24">
            <div>
              <h2 className="text-7xl font-black mb-12 tracking-tighter leading-none">Let's build <br /> your brand.</h2>
              <div className="space-y-8">
                <div className="flex items-center"><Mail className="mr-6 w-8 h-8 text-primary" /> <span className="text-2xl font-black">{settings.contact_email}</span></div>
                <div className="flex items-center"><Phone className="mr-6 w-8 h-8 text-green-500" /> <span className="text-2xl font-black">{settings.contact_phone}</span></div>
              </div>
            </div>
            <div className="bg-white rounded-[48px] p-12 text-gray-900 shadow-2xl">
              <form className="space-y-8" onSubmit={(e) => { e.preventDefault(); alert("Enquiry sent (Simulated)"); }}>
                <input required type="text" placeholder="Your Name" className="w-full bg-gray-50 border-none rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-primary" />
                <input required type="email" placeholder="Email Address" className="w-full bg-gray-50 border-none rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-primary" />
                <textarea rows={4} placeholder="Tell me about your project..." className="w-full bg-gray-50 border-none rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-primary resize-none" />
                <Button fullWidth className="rounded-2xl py-6 text-lg">Send Message</Button>
              </form>
            </div>
          </div>
        </div>
      </section>
      <footer className="bg-gray-950 py-20 text-center text-gray-500 text-xs font-black tracking-widest uppercase">
        <p>&copy; {new Date().getFullYear()} {settings.site_name} STUDIO. ALL RIGHTS RESERVED.</p>
      </footer>
      <FloatingWhatsApp />
    </div>
  );
};

