const AdminLogin = ({ onLogin }: { onLogin: (e: string, p: string) => void }) => {
  const [email, setEmail] = useState('');
  const [pass, setPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handle = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    const res = await db.adminLogin(email, pass);
    if (res.success) {
      onLogin(email, pass);
    } else {
      setError('Invalid credentials');
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-white p-12 rounded-[48px] shadow-2xl w-full max-w-md">
        <div className="w-20 h-20 bg-primary/10 rounded-3xl flex items-center justify-center mx-auto mb-10">
          <Lock className="w-10 h-10 text-primary" />
        </div>
        <h1 className="text-4xl font-black text-center mb-2">Admin Panel</h1>
        <p className="text-gray-400 text-center mb-10">Enter your secure credentials</p>

        {error && <div className="bg-red-50 text-red-500 p-4 rounded-2xl mb-6 text-sm text-center font-bold">{error}</div>}

        <form onSubmit={handle} className="space-y-6">
          <input required type="email" placeholder="Admin Email" className="w-full bg-gray-50 border-none rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-primary" value={email} onChange={e => setEmail(e.target.value)} />
          <input required type="password" placeholder="Password" className="w-full bg-gray-50 border-none rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-primary" value={pass} onChange={e => setPass(e.target.value)} />
          <Button fullWidth className="rounded-2xl py-5" disabled={loading}>
            {loading ? <Loader2 className="animate-spin" /> : 'LOGIN TO CMS'}
          </Button>
        </form>
      </motion.div>
    </div>
  );
};

