const App = () => {
  const [isLogged, setIsLogged] = useState(false);
  const [loading, setLoading] = useState(true);
  const [hash, setHash] = useState(window.location.hash);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [settings, setSettings] = useState<SiteSettings>({
    id: '1', site_name: DEFAULT_NAME, tagline: 'PREMIUM FREELANCE STUDIO', logo_url: '', 
    whatsapp_number: DEFAULT_WA, contact_phone: '+91 95212 07156', contact_email: 'riddhaanleo@gmail.com',
    address: 'India', instagram_url: '#', twitter_url: '#', linkedin_url: '#', footer_text: '',
    seo_description: 'Premium hand-crafted websites designed specifically for Indian startups and professionals.'
  });

  const [plans, setPlans] = useState<PricingPlan[]>(DEFAULT_PRICING);
  const [services, setServices] = useState<Service[]>(DEFAULT_SERVICES);
  const [portfolio, setPortfolio] = useState<Project[]>(DEFAULT_PORTFOLIO);
  const [testimonials, setTestimonials] = useState<Testimonial[]>(DEFAULT_TESTIMONIALS);
  const [inquiries, setInquiries] = useState<Inquiry[]>([]);

  useEffect(() => {
    const init = async () => {
      const handleHash = () => setHash(window.location.hash);
      window.addEventListener('hashchange', handleHash);

      try {
        const [s, p, sv, pt, inq, t] = await Promise.all([
          db.getSiteSettings(), db.getPricingPlans(), db.getServices(), db.getPortfolio(), db.getInquiries(), db.getTestimonials()
        ]);
        if (s) setSettings(s);
        if (p && p.length) setPlans(p);
        if (sv && sv.length) setServices(sv);
        if (pt && pt.length) setPortfolio(pt);
        if (inq && inq.length) setInquiries(inq);
        if (t && t.length) setTestimonials(t);
      } catch (err) {
        console.warn("Using local fallbacks as database connection failed.");
      }

      setIsLogged(db.isAdminLoggedIn());
      setLoading(false);
      return () => window.removeEventListener('hashchange', handleHash);
    };
    init();
  }, []);

  const handleContactSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    const formData = new FormData(e.currentTarget);
    const payload = {
      name: formData.get('name'),
      email: formData.get('email'),
      phone: formData.get('phone') || '',
      message: formData.get('message'),
      plan: 'Inquiry from Contact Form'
    };

    try {
      await db.submitInquiry(payload);
      alert("Success! Your enquiry has been sent. I'll get back to you soon.");
      (e.target as HTMLFormElement).reset();
    } catch (err) {
      alert("There was an error sending your message. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="w-12 h-12 text-primary animate-spin" /></div>;

  if (hash === '#admin') {
    if (!isLogged) return <AdminLogin onLogin={() => setIsLogged(true)} />;
    return <AdminDashboard 
      inquiries={inquiries} 
      onLogout={() => { db.logoutAdmin(); setIsLogged(false); }} 
      stats={{ services: services.length, projects: portfolio.length }} 
    />;
  }

  return (
    <div className="antialiased selection:bg-primary selection:text-white">
      <Navbar />
      <Hero settings={settings} />
      <About />
      <Services services={services} />
      <Portfolio items={portfolio} />
      <Reviews testimonials={testimonials} />
      <Pricing />
      <FAQ />

      <section id="contact" className="py-20 md:py-32 bg-gray-900 text-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 md:gap-24 items-center">
