const App = () => {
  const [isLogged, setIsLogged] = useState(false);
  const [loading, setLoading] = useState(true);
  const [hash, setHash] = useState(window.location.hash);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [settings, setSettings] = useState<SiteSettings>({
    id: '1', site_name: DEFAULT_NAME, tagline: 'PREMIUM FREELANCE STUDIO', logo_url: '', 
    whatsapp_number: DEFAULT_WA, contact_phone: '+91 95212 07156', contact_email: 'riddhaanleo@gmail.com',
    address: 'India', instagram_url: '#', twitter_url: '#', linkedin_url: '#', footer_text: '',
    seo_description: 'Premium hand-crafted websites designed specifically for Indian startups and professionals.'
  });

  const [plans, setPlans] = useState<PricingPlan[]>(DEFAULT_PRICING);
  const [services, setServices] = useState<Service[]>(DEFAULT_SERVICES);
  const [portfolio, setPortfolio] = useState<Project[]>(DEFAULT_PORTFOLIO);
  const [testimonials, setTestimonials] = useState<Testimonial[]>(DEFAULT_TESTIMONIALS);
  const [inquiries, setInquiries] = useState<Inquiry[]>([]);

  useEffect(() => {
    const init = async () => {
      const handleHash = () => setHash(window.location.hash);
      window.addEventListener('hashchange', handleHash);

      try {
        const [s, p, sv, pt, inq, t] = await Promise.all([
          db.getSiteSettings(), db.getPricingPlans(), db.getServices(), db.getPortfolio(), db.getInquiries(), db.getTestimonials()
        ]);
        if (s) setSettings(s);
        if (p && p.length) setPlans(p);
        if (sv && sv.length) setServices(sv);
        if (pt && pt.length) setPortfolio(pt);
        if (inq && inq.length) setInquiries(inq);
        if (t && t.length) setTestimonials(t);
      } catch (err) {
        console.warn("Using local fallbacks.");
      }

      setIsLogged(db.isAdminLoggedIn());
      setLoading(false);
      return () => window.removeEventListener('hashchange', handleHash);
    };
    init();
  }, []);

  const handleContactSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    const formData = new FormData(e.currentTarget);
    const payload = {
      name: formData.get('name'),
      email: formData.get('email'),
      phone: formData.get('phone') || '',
      message: formData.get('message'),
      plan: 'Inquiry from Contact Form'
    };

    try {
      await db.submitInquiry(payload);
      alert("Success! Your enquiry has been sent.");
      (e.target as HTMLFormElement).reset();
    } catch (err) {
      alert("There was an error sending your message.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="w-12 h-12 text-primary animate-spin" /></div>;

  return (
    <div className="antialiased selection:bg-primary selection:text-white">
      <Navbar />
      <Hero settings={settings} />
      <About />
      <Services services={services} />
      <Portfolio items={portfolio} />
      <Reviews testimonials={testimonials} />
      <Pricing />
      <FAQ />

      <section id="contact" className="py-16 md:py-32 bg-gray-900 text-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          {/* Side-by-side on desktop (lg), stacked on mobile/tablet */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-24 items-center">
            <div className="text-center lg:text-left lg:-mt-20">
              <h2 className="text-3xl sm:text-5xl md:text-7xl font-black mb-6 md:mb-8 tracking-tighter leading-tight">Let's talk about <br className="hidden lg:block" /> your big idea.</h2>
              <p className="text-sm md:text-xl text-gray-400 mb-8 md:mb-12 font-medium max-w-lg mx-auto lg:mx-0 leading-relaxed px-4 lg:px-0">
                I'm currently accepting new projects. Fill out the form or send an email to get a response within 12 hours.
              </p>
              <div className="space-y-6 md:space-y-8 flex flex-col items-center lg:items-start">
                <div className="flex items-center">
                  <motion.div
                    animate={{ scale: [1, 1.1, 1] }}
                    transition={{ repeat: Infinity, duration: 2 }}
                    className="mr-4 md:mr-6"
                  >
                    <Mail className="w-6 h-6 md:w-8 md:h-8 text-primary" />
                  </motion.div>
                  <span className="text-base md:text-2xl font-black break-all">{settings.contact_email}</span>
                </div>
                <div className="flex items-center">
                  <motion.div
                    animate={{ y: [0, -4, 0] }}
                    transition={{ repeat: Infinity, duration: 1.5 }}
                    className="mr-4 md:mr-6"
                  >
                    <MessageCircle className="w-6 h-6 md:w-8 md:h-8 text-[#25D366]" />
                  </motion.div>
                  <span className="text-base md:text-2xl font-black">{settings.contact_phone}</span>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-[24px] md:rounded-[48px] p-8 md:p-12 text-gray-900 shadow-2xl mt-8 lg:mt-0">
              <form className="space-y-6 md:space-y-8" onSubmit={handleContactSubmit}>
                <div className="space-y-6 md:space-y-8">
                  <input required name="name" type="text" placeholder="Your Name" className="w-full bg-gray-50 border-none rounded-xl md:rounded-2xl px-5 md:px-6 py-3.5 md:py-4 outline-none focus:ring-2 focus:ring-primary text-xs md:text-base" />
                  <input required name="phone" type="tel" placeholder="Phone Number" className="w-full bg-gray-50 border-none rounded-xl md:rounded-2xl px-5 md:px-6 py-3.5 md:py-4 outline-none focus:ring-2 focus:ring-primary text-xs md:text-base" />
                </div>
                <input required name="email" type="email" placeholder="Email Address" className="w-full bg-gray-50 border-none rounded-xl md:rounded-2xl px-5 md:px-6 py-3.5 md:py-4 outline-none focus:ring-2 focus:ring-primary text-xs md:text-base" />
                <textarea required name="message" rows={4} placeholder="Tell me about your project..." className="w-full bg-gray-50 border-none rounded-xl md:rounded-2xl px-5 md:px-6 py-3.5 md:py-4 outline-none focus:ring-2 focus:ring-primary resize-none text-xs md:text-base" />
