                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Live Demo Link</label>
                    <input className="w-full p-4 bg-gray-50 rounded-2xl outline-none border" value={editingItem.link || ''} onChange={e => setEditingItem({...editingItem, link: e.target.value})} />
                  </div>
                </>
              )}
              {activeTab === 'testimonials' && (
                <>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Client Name</label>
                      <input required className="w-full p-4 bg-gray-50 rounded-2xl outline-none border" value={editingItem.name || ''} onChange={e => setEditingItem({...editingItem, name: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Client Role/Company</label>
                      <input required className="w-full p-4 bg-gray-50 rounded-2xl outline-none border" value={editingItem.role || ''} onChange={e => setEditingItem({...editingItem, role: e.target.value})} />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Avatar Image URL</label>
                    <input className="w-full p-4 bg-gray-50 rounded-2xl outline-none border" value={editingItem.avatar || ''} onChange={e => setEditingItem({...editingItem, avatar: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Review Message</label>
                    <textarea required className="w-full p-4 bg-gray-50 rounded-2xl outline-none border min-h-[120px]" value={editingItem.content || ''} onChange={e => setEditingItem({...editingItem, content: e.target.value})} />
                  </div>
                </>
              )}
              <div className="pt-6">
                <Button fullWidth className="rounded-2xl py-5 h-14" disabled={loading}>
                  {loading ? <Loader2 className="animate-spin" /> : `UPDATE ${activeTab.toUpperCase().slice(0, -1)}`}
                </Button>
              </div>
            </form>
          </motion.div>
        </div>
      )}
    </div>
  );
};

