                  {isSubmitting ? <Loader2 className="animate-spin" /> : 'SUBMIT ENQUIRY'}
                </Button>
              </form>
            </div>
          </div>
        </div>
      </section>

      <Footer settings={settings} />
      <FloatingWhatsApp />
