आपका एरर इसलिए आ रहा है क्योंकि डेटाबेस में `inquiries` नाम की टेबल मौजूद नहीं है या उसकी "Permissions" (RLS) सेट नहीं हैं। 

चूंकि आपने SQL कोड डिलीट कर दिया है, इसलिए **सबसे पहले नीचे दिया गया पूरा SQL कोड अपने Supabase SQL Editor में कॉपी करें और 'Run' बटन दबाएं।** यह आपकी सभी समस्याओं को जड़ से खत्म कर देगा।

### 1. Complete SQL Code (Paste this in Supabase SQL Editor)

```sql
-- 1. Inquiries Table (कांटेक्ट फॉर्म के लिए)
CREATE TABLE IF NOT EXISTS public.inquiries (
    id BIGSERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    phone TEXT,
    message TEXT NOT NULL,
    plan TEXT DEFAULT 'General Inquiry',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Site Settings Table
CREATE TABLE IF NOT EXISTS public.site_settings (
    id TEXT PRIMARY KEY DEFAULT '1',
    site_name TEXT,
    tagline TEXT,
    logo_url TEXT,
    whatsapp_number TEXT,
    contact_phone TEXT,
    contact_email TEXT,
    address TEXT,
    instagram_url TEXT,
    twitter_url TEXT,
    linkedin_url TEXT,
    footer_text TEXT,
    seo_description TEXT
);

-- 3. Services Table
CREATE TABLE IF NOT EXISTS public.services (
    id BIGSERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    description TEXT,
    icon TEXT,
    status TEXT DEFAULT 'active'
);

-- 4. Portfolio Table
CREATE TABLE IF NOT EXISTS public.portfolio (
    id BIGSERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    category TEXT,
    image TEXT,
    description TEXT,
    link TEXT,
    status TEXT DEFAULT 'published'
);

-- 5. Testimonials Table
CREATE TABLE IF NOT EXISTS public.testimonials (
    id BIGSERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    role TEXT,
    content TEXT,
    avatar TEXT,
    rating INTEGER DEFAULT 5,
    status TEXT DEFAULT 'approved'
);

-- 6. FAQs Table
CREATE TABLE IF NOT EXISTS public.faqs (
    id BIGSERIAL PRIMARY KEY,
    question TEXT NOT NULL,
    answer TEXT NOT NULL
);

-- --- SECURITY POLICIES (RLS) ---
-- Enable RLS on all tables
ALTER TABLE public.inquiries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.portfolio ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.testimonials ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.faqs ENABLE ROW LEVEL SECURITY;

-- Allow Public to INSERT Inquiries (ताकि लोग फॉर्म भर सकें)
DROP POLICY IF EXISTS "Public can insert" ON public.inquiries;
CREATE POLICY "Public can insert" ON public.inquiries FOR INSERT WITH CHECK (true);

-- Allow Admin to SEE Inquiries
DROP POLICY IF EXISTS "Admin can view" ON public.inquiries;
CREATE POLICY "Admin can view" ON public.inquiries FOR SELECT TO authenticated USING (true);

-- Allow Public to READ content tables
CREATE POLICY "Public read settings" ON public.site_settings FOR SELECT USING (true);
CREATE POLICY "Public read services" ON public.services FOR SELECT USING (true);
CREATE POLICY "Public read portfolio" ON public.portfolio FOR SELECT USING (true);
CREATE POLICY "Public read testimonials" ON public.testimonials FOR SELECT USING (true);
CREATE POLICY "Public read faqs" ON public.faqs FOR SELECT USING (true);

-- Allow Admin full access
CREATE POLICY "Admin full access settings" ON public.site_settings FOR ALL TO authenticated USING (true);
CREATE POLICY "Admin full access services" ON public.services FOR ALL TO authenticated USING (true);
CREATE POLICY "Admin full access portfolio" ON public.portfolio FOR ALL TO authenticated USING (true);
CREATE POLICY "Admin full access testimonials" ON public.testimonials FOR ALL TO authenticated USING (true);
CREATE POLICY "Admin full access faqs" ON public.faqs FOR ALL TO authenticated USING (true);
```

